-- Phase 22: Integration Platform. Secret values are deliberately never stored here.
CREATE TABLE public.integration_registry (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, name TEXT NOT NULL, integration_type TEXT NOT NULL CHECK (integration_type IN ('telematics','erp','accounting','crm','wms','fuel','gps','cloud_storage','email','sms','identity','iot','customer_api','supplier_api','file_import','file_export','custom')), vendor TEXT NOT NULL, version TEXT NOT NULL DEFAULT 'v1', authentication_type TEXT NOT NULL CHECK(authentication_type IN ('api_key','oauth2','client_credentials','service_account','none')), status TEXT NOT NULL DEFAULT 'configured' CHECK(status IN ('configured','connected','syncing','failed','disabled','awaiting_authentication')), owner_id UUID REFERENCES auth.users(id), environment TEXT NOT NULL DEFAULT 'production' CHECK(environment IN ('production','sandbox','test')), enabled BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,name));
CREATE TABLE public.integration_connections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID NOT NULL REFERENCES public.integration_registry(id) ON DELETE CASCADE, authentication_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'awaiting_authentication' CHECK(status IN ('configured','connected','syncing','failed','disabled','awaiting_authentication')), secret_reference TEXT, oauth_metadata JSONB NOT NULL DEFAULT '{}', service_account_reference TEXT, token_expires_at TIMESTAMPTZ, refresh_reference TEXT, last_successful_sync_at TIMESTAMPTZ, last_attempt_at TIMESTAMPTZ, error_message TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_health (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID NOT NULL REFERENCES public.integration_registry(id) ON DELETE CASCADE, health_area TEXT NOT NULL CHECK(health_area IN ('authentication','connectivity','sync_delay','api_errors','rate_limits','retry_queue','dead_letter_queue')), status TEXT NOT NULL CHECK(status IN ('healthy','warning','critical','unavailable')), detail_metadata JSONB NOT NULL DEFAULT '{}', checked_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(integration_id,health_area));
CREATE TABLE public.integration_api_catalogue (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, name TEXT NOT NULL, endpoint TEXT NOT NULL, version TEXT NOT NULL, exposure TEXT NOT NULL CHECK(exposure IN ('internal','external','public','service')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','deprecated','disabled')), owner_id UUID REFERENCES auth.users(id), authentication_type TEXT NOT NULL, rate_limit_per_minute INTEGER NOT NULL DEFAULT 60 CHECK(rate_limit_per_minute > 0), documentation_url TEXT, example_metadata JSONB NOT NULL DEFAULT '{}', deprecation_notice TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,endpoint,version));
CREATE TABLE public.integration_api_keys (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, name TEXT NOT NULL, key_prefix TEXT NOT NULL, secret_reference TEXT NOT NULL, owner_id UUID NOT NULL REFERENCES auth.users(id), scopes JSONB NOT NULL DEFAULT '[]', expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, last_used_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked','expired')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,key_prefix));
CREATE TABLE public.integration_webhook_endpoints (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), url TEXT NOT NULL CHECK(url ~ '^https?://'), event_type TEXT NOT NULL, secret_reference TEXT, status TEXT NOT NULL DEFAULT 'enabled' CHECK(status IN ('enabled','disabled','awaiting_authentication')), last_delivery_at TIMESTAMPTZ, retry_count INTEGER NOT NULL DEFAULT 0 CHECK(retry_count >= 0), failure_reason TEXT, signature_metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_webhook_deliveries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, webhook_id UUID NOT NULL REFERENCES public.integration_webhook_endpoints(id) ON DELETE CASCADE, event_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','delivering','succeeded','failed','retry_scheduled','dead_letter')), attempt_count INTEGER NOT NULL DEFAULT 0, payload_metadata JSONB NOT NULL DEFAULT '{}', last_error TEXT, delivered_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_event_bus (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, event_type TEXT NOT NULL, aggregate_type TEXT NOT NULL, aggregate_id UUID NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0), source_module TEXT NOT NULL CHECK(source_module IN ('fleet','dispatch','tracking','warehouse','crm','commercial','hr','compliance','procurement','customer_portal','bi')), payload_metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE public.integration_sync_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, source_name TEXT NOT NULL, destination_name TEXT NOT NULL, trigger_type TEXT NOT NULL CHECK(trigger_type IN ('manual','scheduled','triggered')), status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed','cancelled')), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, duration_ms BIGINT, records_processed INTEGER, error_metadata JSONB NOT NULL DEFAULT '{}', retry_count INTEGER NOT NULL DEFAULT 0 CHECK(retry_count >= 0), created_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_retry_queue (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, sync_job_id UUID REFERENCES public.integration_sync_jobs(id) ON DELETE SET NULL, source_type TEXT NOT NULL, source_id UUID NOT NULL, attempt INTEGER NOT NULL CHECK(attempt > 0), maximum_attempts INTEGER NOT NULL CHECK(maximum_attempts > 0), next_retry_at TIMESTAMPTZ, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','processing','completed','exhausted')), backoff_metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(attempt <= maximum_attempts));
CREATE TABLE public.integration_dead_letter_queue (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, source_type TEXT NOT NULL, source_id UUID NOT NULL, payload_metadata JSONB NOT NULL DEFAULT '{}', last_error TEXT NOT NULL, retry_history JSONB NOT NULL DEFAULT '[]', resolution TEXT, closed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,source_type,source_id));
CREATE TABLE public.integration_field_mappings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID NOT NULL REFERENCES public.integration_registry(id) ON DELETE CASCADE, source_entity TEXT NOT NULL, destination_entity TEXT NOT NULL, source_field TEXT, destination_field TEXT NOT NULL, transform_type TEXT NOT NULL CHECK(transform_type IN ('direct','lookup','constant','format','concatenate','split')), required BOOLEAN NOT NULL DEFAULT false, default_value TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK(version > 0), active BOOLEAN NOT NULL DEFAULT true, CHECK(source_field IS NOT NULL OR transform_type='constant'));
CREATE TABLE public.integration_import_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, entity_type TEXT NOT NULL CHECK(entity_type IN ('customers','suppliers','employees','vehicles','inventory','shipments','purchase_orders')), format TEXT NOT NULL CHECK(format IN ('csv','json','spreadsheet_metadata')), status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed','cancelled')), validation_metadata JSONB NOT NULL DEFAULT '{}', error_metadata JSONB NOT NULL DEFAULT '{}', imported_count INTEGER, skipped_count INTEGER, duplicate_count INTEGER, duration_ms BIGINT, requested_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_export_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, domain TEXT NOT NULL CHECK(domain IN ('fleet','warehouse','crm','hr','compliance','procurement','bi')), format TEXT NOT NULL CHECK(format IN ('csv','json','spreadsheet_metadata')), status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','running','completed','failed','cancelled')), delivery_metadata JSONB NOT NULL DEFAULT '{}', error_metadata JSONB NOT NULL DEFAULT '{}', requested_by UUID REFERENCES auth.users(id), completed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, integration_id UUID REFERENCES public.integration_registry(id) ON DELETE SET NULL, alert_type TEXT NOT NULL CHECK(alert_type IN ('authentication_expiry','webhook_failure','api_failure','retry_exhaustion','dlq_growth','integration_disabled','sync_delay','rate_limit_exceeded')), severity TEXT NOT NULL CHECK(severity IN ('info','warning','critical')), title TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', acknowledged_at TIMESTAMPTZ, acknowledged_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.integration_audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id UUID NOT NULL, event_type TEXT NOT NULL, actor_id UUID REFERENCES auth.users(id), metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());

DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['integration_registry','integration_connections','integration_health','integration_api_catalogue','integration_api_keys','integration_webhook_endpoints','integration_webhook_deliveries','integration_event_bus','integration_sync_jobs','integration_retry_queue','integration_dead_letter_queue','integration_field_mappings','integration_import_jobs','integration_export_jobs','integration_alerts','integration_audit_logs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); END LOOP; END $$;
CREATE TRIGGER integration_registry_updated BEFORE UPDATE ON public.integration_registry FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER integration_connections_updated BEFORE UPDATE ON public.integration_connections FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
